int vc4_prepare_binning_cmd(struct drm_device *dev, struct vc4_exec_info *exec)
{
    struct vc4_dev *vc4 = to_vc4_dev(dev);
    struct vc4_bo *bo;
    int ret;
    unsigned int cl_size, shader_records_size, uniforms_size;
    unsigned int cl_offset, shader_records_offset, uniforms_offset;
    void *cl, *shader_records, *uniforms;

    cl_size = exec->binning_cl_size;
    shader_records_size = exec->shader_records_size;
    uniforms_size = exec->uniforms_size;

    if (cl_size + shader_records_size + uniforms_size >
        dev->vram_size)
        return -EINVAL;

    cl_offset = 0;
    shader_records_offset = cl_offset + cl_size;
    uniforms_offset = shader_records_offset + shader_records_size;

    cl = kmalloc(cl_size, GFP_KERNEL);
    if (!cl)
        return -ENOMEM;

    shader_records = kmalloc(shader_records_size, GFP_KERNEL);
    if (!shader_records) {
        kfree(cl);
        return -ENOMEM;
    }

    uniforms = kmalloc(uniforms_size, GFP_KERNEL);
    if (!uniforms) {
        kfree(cl);
        kfree(shader_records);
        return -ENOMEM;
    }

    if (copy_from_user(cl, exec->binning_cl_ptr, cl_size)) {
        ret = -EFAULT;
        goto out_free;
    }

    if (copy_from_user(shader_records, exec->shader_records_ptr,
                         shader_records_size)) {
        ret = -EFAULT;
        goto out_free;
    }

    if (copy_from_user(uniforms, exec->uniforms_ptr, uniforms_size)) {
        ret = -EFAULT;
        goto out_free;
    }

    bo = vc4_bo_create(dev, cl_size + shader_records_size + uniforms_size,
                       0, false);
    if (!bo) {
        ret = -ENOMEM;
        goto out_free;
    }

    memcpy(bo->vaddr + cl_offset, cl, cl_size);
    memcpy(bo->vaddr + shader_records_offset, shader_records,
           shader_records_size);
    memcpy(bo->vaddr + uniforms_offset, uniforms, uniforms_size);

    exec->bo = bo;
    exec->cl_offset = cl_offset;
    exec->shader_records_offset = shader_records_offset;
    exec->uniforms_offset = uniforms_offset;

    ret = vc4_validate_cmd_list(dev, exec);
    if (ret)
        goto out_free_bo;

    ret = vc4_wait_for_previous_render(dev, exec);
    if (ret)
        goto out_free_bo;

    kfree(cl);
    kfree(shader_records);
    kfree(uniforms);

    return 0;

out_free_bo:
    vc4_bo_unreference(bo);
out_free:
    kfree(cl);
    kfree(shader_records);
    kfree(uniforms);
    return ret;
}

