int vc4_get_binning_cmdlist(struct drm_device *dev, struct vc4_exec_info *exec)
{
    struct vc4_dev *vc4 = dev->dev_private;
    struct vc4_bo *bo;
    int ret;
    unsigned int binning_offset;
    unsigned int shader_offset;
    unsigned int uniform_offset;

    binning_offset = exec->binning_cmdlist.offset;
    shader_offset = binning_offset + exec->binning_cmdlist.size;
    uniform_offset = shader_offset + exec->shader_records.size;

    if (uniform_offset > 4 * 1024 * 1024)
        return -EINVAL;

    bo = vc4_bo_create(dev, uniform_offset, false);
    if (!bo)
        return -ENOMEM;

    exec->bo = bo;

    ret = vc4_bo_set_tiling(dev, bo, 0, 0, VC4_TILING_FORMAT_A);
    if (ret)
        goto out_free_bo;

    ret = copy_from_user(bo->vaddr + binning_offset,
                         exec->binning_cmdlist.user_ptr,
                         exec->binning_cmdlist.size);
    if (ret)
        goto out_free_bo;

    ret = copy_from_user(bo->vaddr + shader_offset,
                         exec->shader_records.user_ptr,
                         exec->shader_records.size);
    if (ret)
        goto out_free_bo;

    ret = vc4_bo_emit_relocs(dev, exec, binning_offset);
    if (ret)
        goto out_free_bo;

    ret = vc4_wait_for_idle(dev);
    if (ret)
        goto out_free_bo;

    return 0;

out_free_bo:
    vc4_bo_unreference(bo);
    exec->bo = NULL;
    return ret;
}

int vc4_prepare_binning(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;
    struct drm_gem_cma_object *bo;
    u64 binning_start, binning_end;
    u64 shader_start, shader_end;
    u64 uniforms_start, uniforms_end;
    u32 binning_size, shader_size, uniforms_size;
    void *binning_data, *shader_data, *uniforms_data;

    binning_size = exec->binning_end - exec->binning_start;
    shader_size = exec->shader_end - exec->shader_start;
    uniforms_size = exec->uniforms_end - exec->uniforms_start;

    if (binning_size > 0) {
        binning_data = kvmalloc(binning_size, GFP_KERNEL);
        if (!binning_data)
            return -ENOMEM;

        ret = copy_from_user(binning_data,
                             u64_to_user_ptr(exec->binning_start),
                             binning_size);
        if (ret) {
            kfree(binning_data);
            return -EFAULT;
        }
    }

    if (shader_size > 0) {
        shader_data = kvmalloc(shader_size, GFP_KERNEL);
        if (!shader_data) {
            kfree(binning_data);
            return -ENOMEM;
        }

        ret = copy_from_user(shader_data,
                             u64_to_user_ptr(exec->shader_start),
                             shader_size);
        if (ret) {
            kfree(binning_data);
            kfree(shader_data);
            return -EFAULT;
        }
    }

    if (uniforms_size > 0) {
        uniforms_data = kvmalloc(uniforms_size, GFP_KERNEL);
        if (!uniforms_data) {
            kfree(binning_data);
            kfree(shader_data);
            return -ENOMEM;
        }

        ret = copy_from_user(uniforms_data,
                             u64_to_user_ptr(exec->uniforms_start),
                             uniforms_size);
        if (ret) {
            kfree(binning_data);
            kfree(shader_data);
            kfree(uniforms_data);
            return -EFAULT;
        }
    }

    bo = drm_gem_cma_create(dev, binning_size + shader_size + uniforms_size);
    if (!bo) {
        kfree(binning_data);
        kfree(shader_data);
        kfree(uniforms_data);
        return -ENOMEM;
    }

    ret = drm_gem_cma_get_unmapped_area(&bo->base, 0, binning_size + shader_size + uniforms_size, 0, 0);
    if (IS_ERR_VALUE(ret)) {
        drm_gem_object_put(&bo->base);
        kfree(binning_data);
        kfree(shader_data);
        kfree(uniforms_data);
        return ret;
    }

    ret = drm_gem_cma_mmap(&bo->base, 0, binning_size + shader_size + uniforms_size, 0, 0);
    if (ret) {
        drm_gem_object_put(&bo->base);
        kfree(binning_data);
        kfree(shader_data);
        kfree(uniforms_data);
        return ret;
    }

    exec->bo = bo;
    exec->binning_data = binning_data;
    exec->shader_data = shader_data;
    exec->uniforms_data = uniforms_data;

    binning_start = 0;
    binning_end = binning_start + binning_size;
    shader_start = binning_end;
    shader_end = shader_start + shader_size;
    uniforms_start = shader_end;
    uniforms_end = uniforms_start + uniforms_size;

    exec->binning_bo_offset = binning_start;
    exec->shader_bo_offset = shader_start;
    exec->uniforms_bo_offset = uniforms_start;

    ret = vc4_validate_bin(cmds, binning_data, binning_size);
    if (ret) {
        drm_gem_object_put(&bo->base);
        kfree(binning_data);
        kfree(shader_data);
        kfree(uniforms_data);
        return ret;
    }

    ret = vc4_validate_shader(shader_data, shader_size);
    if (ret) {
        drm_gem_object_put(&bo->base);
        kfree(binning_data);
        kfree(shader_data);
        kfree(uniforms_data);
        return ret;
    }

    ret = vc4_wait_for_rendering_to_complete();
    if (ret) {
        drm_gem_object_put(&bo->base);
        kfree(binning_data);
        kfree(shader_data);
        kfree(uniforms_data);
        return ret;
    }

    return 0;
}

